import SuperJSON from './index.js';
import { processStackString, processStackFrames } from './error-stack.js';
import { sanitizeMessage } from './error-sanitizer.js';

simpleTransformation(
  isError,
  'Error',
  (v, superJson) => {
    const baseError: any = {
      name: v.name,
      message: v.message,
    };

    if ('cause' in v) {
      baseError.cause = v.cause;
    }

    superJson.allowedErrorProps.forEach(prop => {
      baseError[prop] = (v as any)[prop];
    });

    return baseError;
  },
  (v, superJson) => {
    const e = new Error(v.message, { cause: v.cause });
    e.name = v.name;
    e.stack = v.stack;

    superJson.allowedErrorProps.forEach(prop => {
      (e as any)[prop] = v[prop];
    });

    return e;
  }
),

function errorAnnotation(error: Error, superJson: SuperJSON): 'Error' | 'Error/stack' | 'Error/frames' {
  const options = superJson.errorStack;
  if (!options || (options.classFilter.length && !options.classFilter.includes(error.name))) return 'Error';
  return options.mode === 'string' ? 'Error/stack' : options.mode === 'frames' ? 'Error/frames' : 'Error';
}

function serializeError(error: Error, superJson: SuperJSON): any {
  const options = superJson.errorStack;
  const matches = !!options && (!options.classFilter.length || options.classFilter.includes(error.name));
  const seen = new Set<Error>();
  function serializeCause(v: Error, depth: number): any {
    seen.add(v);
    const result: any = { name: v.name, message: matches && options!.sanitizeMessage ? sanitizeMessage(v.message) : v.message };
    if (!options) {
      if ('cause' in v) result.cause = v.cause;
    } else if (options.includeCauses !== 'none' && depth < (options.includeCauses === 'direct' ? 1 : options.maxCauseDepth)) {
      const cause = (v as any).cause;
      if (isError(cause) && !seen.has(cause)) result.cause = serializeCause(cause, depth + 1);
    }
    if (typeof AggregateError !== 'undefined' && v instanceof AggregateError) result.errors = v.errors;
    for (const prop of superJson.allowedErrorProps) {
      if (options && (prop === 'stack' || prop === 'stackFrames' || prop === 'cause' || prop === 'errors')) continue;
      result[prop] = (v as any)[prop];
    }
    if (options && matches && typeof v.stack === 'string') {
      if (options.mode === 'string' && superJson.allowedErrorProps.includes('stack')) result.stack = processStackString(v.stack, options);
      if (options.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) result.stackFrames = processStackFrames(v.stack, options);
    }
    const processor = superJson.errorClassRegistry.getProcessor(v.name);
    return processor ? processor(result) : result;
  }
  return serializeCause(error, 0);
}

function deserializeError(v: any, superJson: SuperJSON): Error {
  const e = new Error(v.message, { cause: v.cause });
  e.name = v.name;
  e.stack = v.stack ?? (Array.isArray(v.stackFrames) ? v.stackFrames.map((frame: { raw: string }) => frame.raw).join('\n') : undefined);
  if ('errors' in v) (e as any).errors = v.errors;
  for (const prop of superJson.allowedErrorProps) {
    if (prop in v) (e as any)[prop] = v[prop];
  }
  if (v.cause && !(v.cause instanceof Error) && typeof v.cause === 'object' && typeof v.cause.name === 'string' && typeof v.cause.message === 'string') (e as any).cause = deserializeError(v.cause, superJson);
  return e;
}

